css_variables_setup.code:
:root {
  /* Backgrounds */
  --bg-primary: #0D0D0D;
  --bg-secondary: #121212;
  --bg-card: #1A1A1A;
  --bg-elevated: #2C2C2C;

  /* Text */
  --text-primary: #FFFFFF;
  --text-secondary: #E0E0E0;
  --text-muted: #B0B0B0;

  /* Neon Accents */
  --neon-pink: #FF0099;
  --neon-cyan: #00FFFF;
  --neon-green: #00FF85;
  --neon-blue: #1E90FF;
  --neon-orange: #FF5722;
  --neon-yellow: #FFEB3B;

  /* Functional */
  --border-default: #444444;
  --border-focus: var(--neon-cyan);
  --shadow-glow-pink: 0 0 20px rgba(255, 0, 153, 0.5);
  --shadow-glow-cyan: 0 0 20px rgba(0, 255, 255, 0.5);
}
